window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b67ba08f2d9fd0e1"]={"versions": [{"id": "FIG-b67ba08f2d9fd0e1", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext der AUTOSAR Classic Platform (SWS E2E Library). Das Diagramm stellt das Software-Modul <code>E2E</code> innerhalb des Komponentendiagramm-Rahmens <code>cmp E2E_Required</code> dar und visualisiert dessen Abhängigkeiten zu erforderlichen externen Schnittstellen der CRC-Bibliothek.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Komponenten / Module</strong>:\n<ul class=\"fig-list\"><li><code>E2E</code> (Stereotyp «module»): Die E2E-Bibliothek als aufrufende Komponente.\n</li></ul>\n</li><li><strong>Schnittstellen (Lollipop-Notation)</strong>:\n<ul class=\"fig-list\"><li><code>Crc_CalculateCRC8</code>: Schnittstelle zur Berechnung einer 8-Bit-Prüfsumme nach Standard-Polynom (SAE J1850).\n</li><li><code>Crc_CalculateCRC8H2F</code>: Schnittstelle zur Berechnung einer 8-Bit-Prüfsumme nach dem 0x2F-Polynom (gemäß E2E Profile 2).\n</li></ul>\n</li><li><strong>Beziehungen / Abhängigkeiten</strong>:\n<ul class=\"fig-list\"><li>Gestrichelte Pfeile vom Modul <code>E2E</code> zu beiden Schnittstellen, jeweils annotiert mit dem Stereotyp <code>«mandatory»</code>, welche die zwingende funktionale Abhängigkeit des E2E-Moduls von diesen CRC-Routinen kennzeichnen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schnittstellen- und Abhängigkeitsmodell ohne explizite zeitliche Sequenzabläufe. Zur Laufzeit ruft das Modul <code>E2E</code> während des Schutzes (E2E_P01Protect / E2E_P02Protect) oder der Prüfung (E2E_P01Check / E2E_P02Check) synchron die jeweiligen Prüfsummen-Routinen <code>Crc_CalculateCRC8</code> bzw. <code>Crc_CalculateCRC8H2F</code> auf.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert verbindliche Implementierungsanforderungen für Integratoren und Entwickler der AUTOSAR E2E-Bibliothek:</p>\n<ul class=\"fig-list\"><li>Beide CRC-Routinen (<code>Crc_CalculateCRC8</code> und <code>Crc_CalculateCRC8H2F</code>) müssen im Systemkontext durch die AUTOSAR CRC-Bibliothek bereitgestellt und zur Link-/Compile-Zeit für das E2E-Modul verfügbar sein.\n</li><li>Ein Fehlen einer dieser Schnittstellen verhindert die vollständige Einbindung der standardisierten E2E-Profile (insbesondere Profil 1 und Profil 2).\n</li></ul>"}, {"id": "FIG-91c66a78fa59a940", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext der AUTOSAR Classic Platform (SWS E2E Library). Das Diagramm stellt das Software-Modul <code>E2E</code> ohne umgebenden Diagrammrahmen dar und visualisiert dessen Abhängigkeiten zu erforderlichen externen Schnittstellen der CRC-Bibliothek.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Komponenten / Module</strong>:\n<ul class=\"fig-list\"><li><code>E2E</code> (Stereotyp «module»): Die E2E-Bibliothek als aufrufende Komponente.\n</li></ul>\n</li><li><strong>Schnittstellen (Lollipop-Notation)</strong>:\n<ul class=\"fig-list\"><li><code>Crc_CalculateCRC8</code>: Schnittstelle zur Berechnung einer 8-Bit-Prüfsumme nach Standard-Polynom (SAE J1850).\n</li><li><code>Crc_CalculateCRC8H2F</code>: Schnittstelle zur Berechnung einer 8-Bit-Prüfsumme nach dem 0x2F-Polynom (gemäß E2E Profile 2).\n</li></ul>\n</li><li><strong>Beziehungen / Abhängigkeiten</strong>:\n<ul class=\"fig-list\"><li>Gestrichelte Pfeile vom Modul <code>E2E</code> zu beiden Schnittstellen, jeweils annotiert mit dem Stereotyp <code>«mandatory»</code>, welche die zwingende funktionale Abhängigkeit des E2E-Moduls von diesen CRC-Routinen kennzeichnen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schnittstellen- und Abhängigkeitsmodell ohne explizite zeitliche Sequenzabläufe. Zur Laufzeit ruft das Modul <code>E2E</code> während des Schutzes (E2E_P01Protect / E2E_P02Protect) oder der Prüfung (E2E_P01Check / E2E_P02Check) synchron die jeweiligen Prüfsummen-Routinen <code>Crc_CalculateCRC8</code> bzw. <code>Crc_CalculateCRC8H2F</code> auf.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert verbindliche Implementierungsanforderungen für Integratoren und Entwickler der AUTOSAR E2E-Bibliothek:</p>\n<ul class=\"fig-list\"><li>Beide CRC-Routinen (<code>Crc_CalculateCRC8</code> und <code>Crc_CalculateCRC8H2F</code>) müssen im Systemkontext durch die AUTOSAR CRC-Bibliothek bereitgestellt und zur Link-/Compile-Zeit für das E2E-Modul verfügbar sein.\n</li><li>Ein Fehlen einer dieser Schnittstellen verhindert die vollständige Einbindung der standardisierten E2E-Profile (insbesondere Profil 1 und Profil 2).\n</li></ul>"}, {"id": "FIG-91dabe173762638f", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext der AUTOSAR Classic Platform (SWS E2E Library). Das Diagramm stellt das Software-Modul <code>E2E</code> ohne umgebenden Diagrammrahmen dar und visualisiert dessen Abhängigkeiten zu erforderlichen externen Schnittstellen der CRC-Bibliothek.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Komponenten / Module</strong>:\n<ul class=\"fig-list\"><li><code>E2E</code> (Stereotyp «module»): Die E2E-Bibliothek als aufrufende Komponente.\n</li></ul>\n</li><li><strong>Schnittstellen (Lollipop-Notation)</strong>:\n<ul class=\"fig-list\"><li><code>Crc_CalculateCRC8</code>: Schnittstelle zur Berechnung einer 8-Bit-Prüfsumme nach Standard-Polynom (SAE J1850).\n</li><li><code>Crc_CalculateCRC8H2F</code>: Schnittstelle zur Berechnung einer 8-Bit-Prüfsumme nach dem 0x2F-Polynom (gemäß E2E Profile 2).\n</li></ul>\n</li><li><strong>Beziehungen / Abhängigkeiten</strong>:\n<ul class=\"fig-list\"><li>Gestrichelte Pfeile vom Modul <code>E2E</code> zu beiden Schnittstellen, jeweils annotiert mit dem Stereotyp <code>«mandatory»</code>, welche die zwingende funktionale Abhängigkeit des E2E-Moduls von diesen CRC-Routinen kennzeichnen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schnittstellen- und Abhängigkeitsmodell ohne explizite zeitliche Sequenzabläufe. Zur Laufzeit ruft das Modul <code>E2E</code> während des Schutzes (E2E_P01Protect / E2E_P02Protect) oder der Prüfung (E2E_P01Check / E2E_P02Check) synchron die jeweiligen Prüfsummen-Routinen <code>Crc_CalculateCRC8</code> bzw. <code>Crc_CalculateCRC8H2F</code> auf.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert verbindliche Implementierungsanforderungen für Integratoren und Entwickler der AUTOSAR E2E-Bibliothek:</p>\n<ul class=\"fig-list\"><li>Beide CRC-Routinen (<code>Crc_CalculateCRC8</code> und <code>Crc_CalculateCRC8H2F</code>) müssen im Systemkontext durch die AUTOSAR CRC-Bibliothek bereitgestellt und zur Link-/Compile-Zeit für das E2E-Modul verfügbar sein.\n</li><li>Ein Fehlen einer dieser Schnittstellen verhindert die vollständige Einbindung der standardisierten E2E-Profile (insbesondere Profil 1 und Profil 2).\n</li></ul>"}], "trans": [{"from": "FIG-b67ba08f2d9fd0e1", "to": "FIG-91c66a78fa59a940", "fr": "R3.2.3", "tr": "R4.0.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Umgebender Diagrammrahmen mit Kopfzeile <code>cmp E2E_Required</code> entfernt.\n</li><li>Unterer Bildbeschnitt leicht nach oben verschoben, wodurch der Text <code>Crc_CalculateCRC8H2F</code> an der Grundlinie geringfügig abgeschnitten wird.\n</li></ul>"}, {"from": "FIG-91c66a78fa59a940", "to": "FIG-91dabe173762638f", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
